package org.bukkit.configuration.file;
public class FileConfiguration {
 private final java.util.Map<String,String> values=new java.util.LinkedHashMap<>();
 public void loadFromString(String text){values.clear();java.util.List<String> keys=new java.util.ArrayList<>();java.util.List<Integer> indents=new java.util.ArrayList<>();for(String line:text.split("\n")){String t=line.trim();if(t.isEmpty()||t.startsWith("#"))continue;int n=line.indexOf(t),c=t.indexOf(':');if(c<1)throw new IllegalArgumentException("Поддерживаются только YAML-скаляры и секции");while(!indents.isEmpty()&&n<=indents.get(indents.size()-1)){indents.remove(indents.size()-1);keys.remove(keys.size()-1);}String k=t.substring(0,c).trim(),v=t.substring(c+1).trim();String path=String.join(".",keys);if(!path.isEmpty())path+=".";if(v.isEmpty()){keys.add(k);indents.add(n);}else{if(v.startsWith("[")||v.startsWith("{")||v.startsWith("|")||v.startsWith(">")||v.startsWith("&")||v.startsWith("*"))throw new IllegalArgumentException("Сложный YAML не поддерживается");if(v.startsWith("'")){if(!v.endsWith("'"))throw new IllegalArgumentException("Незакрытая строка");v=v.substring(1,v.length()-1).replace("''","'");}else if(v.startsWith("\"")){throw new IllegalArgumentException("Используйте одинарные кавычки YAML");}else{int comment=v.indexOf(" #");if(comment>=0)v=v.substring(0,comment).trim();}values.put(path+k,v);}}}
 public String getString(String p){return getString(p,null);}public String getString(String p,String d){return values.containsKey(p)?values.get(p):d;}
 public int getInt(String p){return getInt(p,0);}public int getInt(String p,int d){try{return Integer.parseInt(values.get(p));}catch(Exception e){return d;}}
 public long getLong(String p){return getLong(p,0);}public long getLong(String p,long d){try{return Long.parseLong(values.get(p));}catch(Exception e){return d;}}
 public boolean getBoolean(String p){return getBoolean(p,false);}public boolean getBoolean(String p,boolean d){String v=values.get(p);return v==null?d:Boolean.parseBoolean(v);}
 public boolean contains(String p){return values.containsKey(p);}public void set(String p,Object v){if(v==null)values.remove(p);else values.put(p,v.toString());}
 public String saveToString(){StringBuilder b=new StringBuilder();for(java.util.Map.Entry<String,String> e:values.entrySet())b.append(e.getKey()).append(": '").append(e.getValue().replace("'","''")).append("'\n");return b.toString();}
}
